#[test]
fn unit_metadata() {
    let info = Luminance::<f64>::INFO;
    assert_eq!(info.name, "Luminance");
    assert_eq!(info.units.len(), LuminanceUnit::ALL.len());
    for (&unit, unit_info) in LuminanceUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, LuminanceUnit::CandelaPerSquareMeter.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Luminance::new(v, LuminanceUnit::CandelaPerSquareMeter),
        Luminance::from_candelas_per_square_meter(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::CandelaPerSquareMeter),
        Luminance::from_base(v).as_candelas_per_square_meter()
    );
    assert_eq!(
        Luminance::new(v, LuminanceUnit::NanocandelaPerSquareMeter),
        Luminance::from_nanocandelas_per_square_meter(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::NanocandelaPerSquareMeter),
        Luminance::from_base(v).as_nanocandelas_per_square_meter()
    );
    assert_eq!(
        Luminance::new(v, LuminanceUnit::MicrocandelaPerSquareMeter),
        Luminance::from_microcandelas_per_square_meter(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::MicrocandelaPerSquareMeter),
        Luminance::from_base(v).as_microcandelas_per_square_meter()
    );
    assert_eq!(
        Luminance::new(v, LuminanceUnit::MillicandelaPerSquareMeter),
        Luminance::from_millicandelas_per_square_meter(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::MillicandelaPerSquareMeter),
        Luminance::from_base(v).as_millicandelas_per_square_meter()
    );
    assert_eq!(
        Luminance::new(v, LuminanceUnit::CenticandelaPerSquareMeter),
        Luminance::from_centicandelas_per_square_meter(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::CenticandelaPerSquareMeter),
        Luminance::from_base(v).as_centicandelas_per_square_meter()
    );
    assert_eq!(
        Luminance::new(v, LuminanceUnit::DecicandelaPerSquareMeter),
        Luminance::from_decicandelas_per_square_meter(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::DecicandelaPerSquareMeter),
        Luminance::from_base(v).as_decicandelas_per_square_meter()
    );
    assert_eq!(
        Luminance::new(v, LuminanceUnit::KilocandelaPerSquareMeter),
        Luminance::from_kilocandelas_per_square_meter(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::KilocandelaPerSquareMeter),
        Luminance::from_base(v).as_kilocandelas_per_square_meter()
    );
    assert_eq!(
        Luminance::new(v, LuminanceUnit::CandelaPerSquareFoot),
        Luminance::from_candelas_per_square_foot(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::CandelaPerSquareFoot),
        Luminance::from_base(v).as_candelas_per_square_foot()
    );
    assert_eq!(
        Luminance::new(v, LuminanceUnit::CandelaPerSquareInch),
        Luminance::from_candelas_per_square_inch(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::CandelaPerSquareInch),
        Luminance::from_base(v).as_candelas_per_square_inch()
    );
    assert_eq!(
        Luminance::new(v, LuminanceUnit::Nit),
        Luminance::from_nits(v)
    );
    assert_eq!(
        Luminance::from_base(v).convert_to(LuminanceUnit::Nit),
        Luminance::from_base(v).as_nits()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Luminance; 10] = [
        Luminance::const_new(1234.5, LuminanceUnit::CandelaPerSquareMeter),
        Luminance::const_new(1234.5, LuminanceUnit::NanocandelaPerSquareMeter),
        Luminance::const_new(1234.5, LuminanceUnit::MicrocandelaPerSquareMeter),
        Luminance::const_new(1234.5, LuminanceUnit::MillicandelaPerSquareMeter),
        Luminance::const_new(1234.5, LuminanceUnit::CenticandelaPerSquareMeter),
        Luminance::const_new(1234.5, LuminanceUnit::DecicandelaPerSquareMeter),
        Luminance::const_new(1234.5, LuminanceUnit::KilocandelaPerSquareMeter),
        Luminance::const_new(1234.5, LuminanceUnit::CandelaPerSquareFoot),
        Luminance::const_new(1234.5, LuminanceUnit::CandelaPerSquareInch),
        Luminance::const_new(1234.5, LuminanceUnit::Nit),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(LuminanceUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Luminance::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in LuminanceUnit::ALL {
            assert_eq!(
                Luminance::const_new(v, unit).as_base().to_bits(),
                Luminance::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Luminance::from_base(v);
        let auto = q.auto_unit();
        assert_close(Luminance::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in LuminanceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Luminance::from_base(0.0).auto_unit().unit,
        LuminanceUnit::CandelaPerSquareMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Cd/m²".parse::<LuminanceUnit>(),
        Ok(LuminanceUnit::CandelaPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "Cd/m²").parse::<Luminance>(),
        Ok(Luminance::new(2.5, LuminanceUnit::CandelaPerSquareMeter))
    );
    assert_eq!(
        "nCd/m²".parse::<LuminanceUnit>(),
        Ok(LuminanceUnit::NanocandelaPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "nCd/m²").parse::<Luminance>(),
        Ok(Luminance::new(
            2.5,
            LuminanceUnit::NanocandelaPerSquareMeter
        ))
    );
    assert_eq!(
        "µCd/m²".parse::<LuminanceUnit>(),
        Ok(LuminanceUnit::MicrocandelaPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "µCd/m²").parse::<Luminance>(),
        Ok(Luminance::new(
            2.5,
            LuminanceUnit::MicrocandelaPerSquareMeter
        ))
    );
    assert_eq!(
        "mCd/m²".parse::<LuminanceUnit>(),
        Ok(LuminanceUnit::MillicandelaPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "mCd/m²").parse::<Luminance>(),
        Ok(Luminance::new(
            2.5,
            LuminanceUnit::MillicandelaPerSquareMeter
        ))
    );
    assert_eq!(
        "cCd/m²".parse::<LuminanceUnit>(),
        Ok(LuminanceUnit::CenticandelaPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "cCd/m²").parse::<Luminance>(),
        Ok(Luminance::new(
            2.5,
            LuminanceUnit::CenticandelaPerSquareMeter
        ))
    );
    assert_eq!(
        "dCd/m²".parse::<LuminanceUnit>(),
        Ok(LuminanceUnit::DecicandelaPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "dCd/m²").parse::<Luminance>(),
        Ok(Luminance::new(
            2.5,
            LuminanceUnit::DecicandelaPerSquareMeter
        ))
    );
    assert_eq!(
        "kCd/m²".parse::<LuminanceUnit>(),
        Ok(LuminanceUnit::KilocandelaPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "kCd/m²").parse::<Luminance>(),
        Ok(Luminance::new(
            2.5,
            LuminanceUnit::KilocandelaPerSquareMeter
        ))
    );
    assert_eq!(
        "Cd/ft²".parse::<LuminanceUnit>(),
        Ok(LuminanceUnit::CandelaPerSquareFoot)
    );
    assert_eq!(
        format!("2.5 {}", "Cd/ft²").parse::<Luminance>(),
        Ok(Luminance::new(2.5, LuminanceUnit::CandelaPerSquareFoot))
    );
    assert_eq!(
        "Cd/in²".parse::<LuminanceUnit>(),
        Ok(LuminanceUnit::CandelaPerSquareInch)
    );
    assert_eq!(
        format!("2.5 {}", "Cd/in²").parse::<Luminance>(),
        Ok(Luminance::new(2.5, LuminanceUnit::CandelaPerSquareInch))
    );
    assert_eq!("nt".parse::<LuminanceUnit>(), Ok(LuminanceUnit::Nit));
    assert_eq!(
        format!("2.5 {}", "nt").parse::<Luminance>(),
        Ok(Luminance::new(2.5, LuminanceUnit::Nit))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Luminance>(),
        Err(ParseError::UnknownUnit)
    );
}

